mapper.select:
SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND master_source_system = #{query.sourceSystem}
  AND master_source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND deleted = 0
  AND CAST(company_code AS BINARY) IN

      CAST(#{companyCode} AS BINARY)


  AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')


  AND status = #{query.status}

ORDER BY contract_no, id
LIMIT #{query.offset}, #{query.limit}

SELECT *
FROM com_contract
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.contractId}
  AND deleted = 0
FOR UPDATE
